def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]

    for color in set(x for row in grid for x in row) - {background}:
        # Integral image for fast rectangle counts.
        sums = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                sums[r + 1][c + 1] = (
                    sums[r][c + 1] + sums[r + 1][c] - sums[r][c]
                    + (grid[r][c] == color)
                )

        for r1 in range(h):
            for r2 in range(r1 + 1, h):
                rh = r2 - r1 + 1
                for c1 in range(w):
                    for c2 in range(c1 + 1, w):
                        area = rh * (c2 - c1 + 1)
                        if area < 6:
                            continue
                        count = (sums[r2 + 1][c2 + 1] - sums[r1][c2 + 1]
                                 - sums[r2 + 1][c1] + sums[r1][c1])
                        if count >= 5 and count * 4 >= area * 3:
                            for r in range(r1, r2 + 1):
                                for c in range(c1, c2 + 1):
                                    out[r][c] = color

    return out
